using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;
public static class AdminBoundaryPolicy {
 private static int checks;
 private static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}
 private static object Call(Type t,string name,object receiver,params object[] args){return t.GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance).Invoke(receiver,args);}
 private static object Field(Type t,string name,object receiver){return t.GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(receiver);}
 private static void Set(Type t,string name,object receiver,object value){t.GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(receiver,value);}
 public static int Main(string[] args){try{if(args.Length!=1)throw new Exception("Package root required");string root=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=delegate(object sender,ResolveEventArgs e){string name=new AssemblyName(e.Name).Name;if(name=="Microsoft.Web.WebView2.Core"||name=="Microsoft.Web.WebView2.Wpf")return Assembly.LoadFrom(Path.Combine(root,"runtime","webview2-sdk","1.0.4191.47",name+".dll"));return null;};
 Assembly a=Assembly.LoadFrom(Path.Combine(root,"JA21-Silicon-Console.exe"));Type h=a.GetType("VBJA21.HostAdminBridge",true);string previous=Environment.GetEnvironmentVariable("JA21_CONSOLE_MODE");Environment.SetEnvironmentVariable("JA21_CONSOLE_MODE","1");
 try{Check((bool)Call(h,"TrustedSource",null,"https://ja21-silicon.invalid/index.html"),"sealed exact index source");foreach(string bad in new string[]{"http://ja21-silicon.invalid/index.html","https://ja21-silicon.invalid/validate.html","https://ja21-silicon.invalid/","https://ja21-silicon.invalid/index.html?x=1","https://ja21-silicon.invalid/index.html#x","https://ja21-silicon.invalid:443/index.html","https://JA21-SILICON.INVALID/index.html","https://user@ja21-silicon.invalid/index.html","https://ja21-silicon.invalid.evil/index.html","https://ja21-silicon.invalid./index.html","http://127.0.0.1:8788/index.html","about:blank"})Check(!(bool)Call(h,"TrustedSource",null,bad),"foreign native document");
 Type paths=a.GetType("VBJA21.PortablePaths",true);string boundary="D:\\"+new string('x',147);Check(boundary.Length==150,"profile fixture is 150 UTF16 characters");Call(paths,"RequireConsoleProfilePath",null,boundary);Check(true,"150-character profile budget accepted without filesystem IO");foreach(int length in new int[]{151,200}){bool refused=false;try{Call(paths,"RequireConsoleProfilePath",null,"D:\\"+new string('x',length-3));}catch(TargetInvocationException e){refused=e.InnerException!=null&&e.InnerException.Message.StartsWith("PROFILE_PATH_TOO_LONG:",StringComparison.Ordinal);}Check(refused,"over-budget profile rejected before IO");}string unicode="D:\\"+new string('\u03a9',147);Check(unicode.Length==150,"Unicode fixture counts UTF16 characters");Call(paths,"RequireConsoleProfilePath",null,unicode);Check(true,"Unicode boundary accepted without filesystem IO");
 string token="0123456789abcdef0123456789abcdef";Check((bool)Call(h,"NativeToken",null,new Dictionary<string,object>{{"bridgeEpoch",token}},token),"matching document token");foreach(object value in new object[]{null,42,token+"a","ffffffffffffffffffffffffffffffff"})Check(!(bool)Call(h,"NativeToken",null,new Dictionary<string,object>{{"bridgeEpoch",value}},token),"old or malformed document token");Check(!(bool)Call(h,"NativeToken",null,new Dictionary<string,object>(),token),"missing document token");
 List<Action> ui=new List<Action>();object bridge=Activator.CreateInstance(h,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{root,null,new Action<Action>(delegate(Action action){ui.Add(action);})},CultureInfo.InvariantCulture);
 try{Set(h,"completed",bridge,true);for(int i=0;i<5000;i++)Call(h,"Post",bridge,"{}",0);Check(((ICollection)Field(h,"output",bridge)).Count<=1024,"pending output item bound");Check((int)Field(h,"outputBytes",bridge)<=524288,"pending output byte bound");Check(ui.Count<=2,"single drain and one overflow closure");Check((bool)Field(h,"outputFailed",bridge),"overflow explicitly failed");int count=((ICollection)Field(h,"output",bridge)).Count,scheduled=ui.Count;Call(h,"Post",bridge,"stale",1);Check(((ICollection)Field(h,"output",bridge)).Count==count&&ui.Count==scheduled,"stale generation cannot queue output");Set(h,"completed",bridge,false);Call(h,"Post",bridge,"incomplete",0);Check(((ICollection)Field(h,"output",bridge)).Count==count&&ui.Count==scheduled,"incomplete document cannot queue output");}
 finally{((IDisposable)bridge).Dispose();}Check(((ICollection)Field(h,"output",bridge)).Count==0,"dispose clears queued output");
 }finally{Environment.SetEnvironmentVariable("JA21_CONSOLE_MODE",previous);}Console.WriteLine("{\"status\":\"PASS\",\"assertions\":"+checks+",\"uacStarted\":false,\"powershellStarted\":false,\"webViewWindowCreated\":false,\"scope\":\"Actual compiled native source and document token checks; dispatcher queue fixtures do not execute UI callbacks or start the bridge\"}");return 0;}catch(Exception e){Console.Error.WriteLine(e.ToString());return 1;}}
}
